import { html } from "../../../../html.js";
import { useMemo, useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, EmptyState, Icon, StatusPill } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";
import { orgLabels, projectFixtures } from "./data.js";

function Toast({message}){return message&&html`<div class="p-projects-toast" role="status">${message}</div>`}
function Health({project}){return html`<${StatusPill} status=${project.health==='Passing'?'done':project.health==='Blocked'?'error':project.health==='Attention'?'waiting-ci':project.health}/>`}
function AddProject({close,notify}){const [repo,setRepo]=useState('');return html`<${Dialog} onClose=${close}><form class="p-projects-dialog" onSubmit=${e=>{e.preventDefault();notify('Project connected on atlas-mac');close()}}><p>CONNECT REPOSITORY</p><h2>Add project</h2><label>Repository URL or local path<input autoFocus required value=${repo} onInput=${e=>setRepo(e.target.value)} placeholder="github.com/acme/service"/></label><label>Device<select><option>atlas-mac</option><option>build-east</option><option>forge-linux</option></select></label><div><button type="button" onClick=${close}>Cancel</button><button class="p-projects-primary" disabled=${!repo.trim()}>Connect project</button></div></form></${Dialog}>`}
function Header({openAdd}){return html`<header class="p-projects-head"><div><p>PROJECT CONTEXTS</p><h1>Projects</h1><span>Repositories, branches, and worktrees available to your agents.</span></div><button class="p-projects-primary" onClick=${openAdd}><${Icon} name="plus"/>Add project</button></header>`}
function Grouped({openAdd,notify}){const [expanded,setExpanded]=useState('durable-web');const groups=Object.keys(orgLabels);return html`<main class="e-page p-projects-page"><${Header} openAdd=${openAdd}/><section class="p-projects-grouped">${groups.map(org=>html`<section class="p-projects-org"><h2>${orgLabels[org]} <small>${projectFixtures.filter(p=>p.org===org).length} repositories</small></h2>${projectFixtures.filter(p=>p.org===org).map(p=>html`<article class="p-projects-repo"><button class="p-projects-repo-head" onClick=${()=>setExpanded(expanded===p.id?'':p.id)}><span><${Icon} name="git-branch"/></span><strong>${p.repo}</strong><em>${p.branch}</em><${Health} project=${p}/><small>${p.open} open</small><${Icon} name=${expanded===p.id?'chevron-up':'chevron-down'}/></button>${expanded===p.id&&html`<div class="p-projects-branches">${p.worktrees.map(w=>html`<div><b>${w[0]}</b><span>${w[1]}</span><span>${w[2]}</span><i>${w[3]}</i></div>`)}<footer><button onClick=${()=>notify(`${p.repo} workspace opened`)}>Open context</button><button onClick=${()=>notify(`${p.repo} archived`)}>Archive</button></footer></div>`}</article>`)}</section>`)}</section></main>`}
function Cards({openAdd,notify}){const [filter,setFilter]=useState('All');const shown=filter==='All'?projectFixtures:projectFixtures.filter(p=>p.health===filter);return html`<main class="e-page p-projects-page"><${Header} openAdd=${openAdd}/><div class="p-projects-card-tools"><div class="p-projects-filters">${['All','Passing','Attention','Blocked','Review'].map(f=>html`<button class=${filter===f?'on':''} onClick=${()=>setFilter(f)}>${f}</button>`)}</div><span>${shown.length} contexts · 14 active conversations</span></div>${shown.length?html`<section class="p-projects-cards">${shown.map(p=>html`<article class="p-projects-card"><div class="p-projects-card-top"><span class="p-projects-repo-mark"><${Icon} name="git-branch"/></span><${Health} project=${p}/></div><h2>${p.repo}</h2><p>${p.url}</p><div class="p-projects-card-stats"><span><b>${p.open}</b> open conversations</span><span><b>${p.prs}</b> pull requests</span></div><div class="p-projects-card-foot"><span>${p.device}</span><button onClick=${()=>notify(`${p.repo} selected`)}>Inspect <${Icon} name="arrow-up-right"/></button></div></article>`)}</section>`:html`<${EmptyState}>No projects match this health filter.</${EmptyState}>`}</main>`}
function Detail({openAdd,notify}){const [project,setProject]=useState(projectFixtures[0]);const [tab,setTab]=useState('Worktrees');const [access,setAccess]=useState(project.agents);const toggle=id=>setAccess(access.includes(id)?access.filter(x=>x!==id):[...access,id]);return html`<main class="e-page p-projects-page p-projects-detail"><${Header} openAdd=${openAdd}/><div class="p-projects-detail-grid"><aside class="p-projects-detail-list"><input aria-label="Find project" placeholder="Find project"/><div>${projectFixtures.map(p=>html`<button class=${p.id===project.id?'on':''} onClick=${()=>{setProject(p);setAccess(p.agents)}}><b>${p.repo}</b><span>${p.open} conversations · ${p.activity}</span></button>`)}</div></aside><section class="p-projects-inspect"><div class="p-projects-inspect-title"><div><p>${orgLabels[project.org]}</p><h2>${project.repo}</h2><span>${project.url} · default <b>${project.branch}</b></span></div><${Health} project=${project}/></div><div class="p-projects-tabs">${['Worktrees','Conversations','Access','Settings'].map(x=>html`<button class=${tab===x?'on':''} onClick=${()=>setTab(x)}>${x}</button>`)}</div>${tab==='Worktrees'&&html`<div class="p-projects-worktrees"><div class="p-projects-worktree-head"><span>Branch / worktree</span><span>Device</span><span>State</span></div>${project.worktrees.map(w=>html`<div><span><b>${w[0]}</b><small>${w[1]}</small></span><span>${w[2]}</span><span>${w[3]}</span></div>`)}</div>`}${tab==='Conversations'&&html`<div class="p-projects-conversations">${project.conversations.map((c,i)=>html`<article><span class=${i===0?'p-projects-live':''}></span><div><b>${c}</b><small>${i===0?'Active now':'Updated '+(i+4)+'m ago'}</small></div><button onClick=${()=>notify(`${c} opened`)}>Open</button></article>`)}</div>`}${tab==='Access'&&html`<div class="p-projects-access"><p>Only selected agents can attach this project to a conversation.</p>${['atlas','beacon','forge','moss'].map(a=>html`<label><input type="checkbox" checked=${access.includes(a)} onInput=${()=>toggle(a)}/><span>${a}</span><small>${access.includes(a)?'Allowed':'No access'}</small></label>`)}</div>`}${tab==='Settings'&&html`<div class="p-projects-settings"><label>Default branch<input value=${project.branch} readOnly/></label><label>Repository URL<input value=${project.url} readOnly/></label><button onClick=${()=>notify(`${project.repo} archived`)}>Archive project</button></div>`}</section></div></main>`}
export default function ProjectsPage(){const [toast,setToast]=useState('');const [adding,setAdding]=useState(false);const notify=message=>{setToast(message);setTimeout(()=>setToast(''),2500)};const openAdd=()=>setAdding(true);return html`<${PageVariants} variants=${[{key:'1',name:'Repository map',render:()=>html`<${Grouped} openAdd=${openAdd} notify=${notify}/>`},{key:'2',name:'Health cards',render:()=>html`<${Cards} openAdd=${openAdd} notify=${notify}/>`},{key:'3',name:'Project detail',render:()=>html`<${Detail} openAdd=${openAdd} notify=${notify}/>`}]}/>${adding&&html`<${AddProject} close=${()=>setAdding(false)} notify=${notify}/>`}<${Toast} message=${toast}/>`}
